// Rebuilds app.bundle.js from core.js + db.js + example-import.json + app.js.
// The bundle is a single classic script so the app works from file:// as well as HTTPS.
// Usage: node work/build-file-bundle.mjs
import {readFileSync, writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname, join} from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = name => readFileSync(join(root, name), 'utf8');
const stripExports = src => src.replace(/^export /gm, '');
const stripImports = src => src.replace(/^import [^;]*;\n/gm, '');
const example = JSON.stringify(JSON.parse(read('example-import.json')));

const parts = [
  '/* Generated by work/build-file-bundle.mjs. Works from file:// and HTTPS. */',
  '(() => {',
  "'use strict';",
  stripExports(read('core.js')),
  stripExports(read('db.js')),
  `const EXAMPLE_IMPORT=${example};`,
  stripImports(read('app.js')),
  '})();',
  ''
];
writeFileSync(join(root, 'app.bundle.js'), parts.join('\n'));
console.log('app.bundle.js rebuilt');
